  const [customRules, setCustomRules] = useState('{"headers":[],"body":[]}')
  const [cooldownRules, setCooldownRules] = useState('{"rules":[]}')
  const [management, setManagement] = useState('{"profile":""}')
  const [managementResult, setManagementResult] = useState<unknown>(null)
  const [oauthResult, setOauthResult] = useState<unknown>(null)
  const [selectedIds, setSelectedIds] = useState<number[]>([])
  const [refreshMode, setRefreshMode] = useState<'merge' | 'replace'>('merge')
  const [channelOperationResult, setChannelOperationResult] = useState<unknown>(null)
  const [urlIndex, setUrlIndex] = useState(0)
  const [urlTestResult, setUrlTestResult] = useState<unknown>(null)
  const [websocketProbeResult, setWebsocketProbeResult] = useState<unknown>(null)
  const [duplicateResult, setDuplicateResult] = useState<unknown>(null)
  const [urlStats, setUrlStats] = useState<ChannelURLStat[]>([])
  const [keyStates, setKeyStates] = useState<Array<{ disabled?: boolean; cooldown_until?: number }>>([])
  const resultText = (value: unknown): string => String(JSON.stringify(value ?? null, null, 2))
  const batchEnabled = async (enabled: boolean) => { if (selectedIds.length === 0) return; await postJSON('/admin/channels/batch-enabled', { channel_ids: selectedIds, enabled }); setSelectedIds([]); query.refresh() }
  const batchClearCooldowns = async () => { if (selectedIds.length === 0) return; await postJSON('/admin/channels/batch-clear-cooldowns', { channel_ids: selectedIds }); setSelectedIds([]); query.refresh() }
  const batchDelete = async () => { if (selectedIds.length === 0 || !window.confirm(`确定删除 ${selectedIds.length} 个渠道？`)) return; await postJSON('/admin/channels/batch-delete', { channel_ids: selectedIds }); setSelectedIds([]); query.refresh() }
  const batchRefreshModels = async () => { if (!selectedIds.length) return; setChannelOperationResult(await postJSON('/admin/channels/models/refresh-batch', { channel_ids: selectedIds, mode: refreshMode })); query.refresh() }
  const batchDeleteModels = async () => { const modelNames = window.prompt('输入要批量删除的模型名称，逗号分隔'); if (!modelNames?.trim() || !selectedIds.length) return; setChannelOperationResult(await postJSON('/admin/channels/models/batch-delete', { operations: selectedIds.map((channel_id) => ({ channel_id, models: modelNames.split(',').map((item) => item.trim()).filter(Boolean) })) })); query.refresh() }
  const batchPriority = async () => { const priority = Number(window.prompt('输入新的优先级')); if (!Number.isInteger(priority) || !selectedIds.length) return; await postJSON('/admin/channels/batch-priority', { updates: selectedIds.map((id) => ({ id, priority })) }); query.refresh() }
  const batchPatchProtocol = async () => { const mode = window.prompt('协议转换模式：auto / off / anthropic / openai / codex / gemini', 'auto'); if (!mode || !selectedIds.length) return; setChannelOperationResult(await postJSON('/admin/channels/batch-advanced', { channel_ids: selectedIds, patch: { protocol_transform_mode: mode } })); query.refresh() }
  const testURL = async () => { if (!editing || !form.urls[urlIndex]?.url || !form.models.length || !form.api_keys?.length) return; setUrlTestResult(await postJSON(`/admin/channels/${editing.id}/test-url`, { model: typeof form.models[0] === 'string' ? form.models[0] : form.models[0].model, stream: true, content: 'test', client_protocol: 'anthropic', key_index: 0, base_url: form.urls[urlIndex].url })) }
  const probeWebsocket = async () => { if (!form.urls[0]?.url || !form.api_keys?.[0]) return; setWebsocketProbeResult(await postJSON('/admin/channels/websocket-probe', { url: form.urls[0].url, api_key: typeof form.api_keys[0] === 'string' ? form.api_keys[0] : form.api_keys[0].api_key, proxy_url: form.proxy_url ?? '' })) }
  const checkDuplicate = async () => { setDuplicateResult(await postJSON('/admin/channels/check-duplicate', { urls: form.urls.map((item) => item.url).filter(Boolean) })) }
  const managementAction = async (kind: 'balance' | 'checkin') => { if (!editing) return; setManagementResult(await postJSON(`/admin/channels/${editing.id}/management-account/${kind}`)); query.refresh() }
  const oauthAction = async (kind: 'usage' | 'quota' | 'codebuddy') => { if (!editing) return; const endpoint = kind === 'usage' ? `/admin/channels/${editing.id}/oauth-usage` : kind === 'quota' ? `/admin/channels/${editing.id}/codex-quota-reset` : `/admin/channels/${editing.id}/codebuddy-checkin`; setOauthResult(await postJSON(endpoint, {})); query.refresh() }
  const query = usePageData(() => getPaginated<Channel>('/admin/channels', { limit: 100, offset: 0, search }), { data: [], count: 0 })
  const channels = query.data.data.filter((channel) => !search || channel.name.toLowerCase().includes(search.toLowerCase()))
  const openCreate = () => { setEditing(null); setAdvancedOpen(false); setManagementOpen(false); setCustomRules('{"headers":[],"body":[]}'); setCooldownRules('{"rules":[]}'); setManagement('{"profile":""}'); setUrlStats([]); setKeyStates([]); setForm({ name: '', auth_type: 'api_key', urls: [{ url: '' }], priority: 0, enabled: true, models: [], api_keys: [] }) }
  const openEdit = async (channel: Channel) => { setEditing(channel); const detail = await getJSON<Channel>(`/admin/channels/${channel.id}`); const keys = await getJSON<Array<Record<string, unknown>>>(`/admin/channels/${channel.id}/keys`); const stats = await getJSON<ChannelURLStat[]>(`/admin/channels/${channel.id}/url-stats`).catch(() => []); setUrlStats(stats); setKeyStates(keys.map((key) => ({ disabled: Boolean(key.disabled), cooldown_until: Number(key.cooldown_until ?? 0) }))); setCustomRules(JSON.stringify(detail.custom_request_rules ?? { headers: [], body: [] }, null, 2)); setCooldownRules(JSON.stringify(detail.cooldown_detection_rules ?? { rules: [] }, null, 2)); setManagement(JSON.stringify(detail.management_account ?? { profile: '' }, null, 2)); setForm({ name: String(detail.name ?? channel.name), auth_type: String(detail.auth_type ?? 'api_key'), urls: Array.isArray(detail.urls) ? detail.urls as ChannelForm['urls'] : [{ url: '' }], priority: Number(detail.priority ?? 0), enabled: detail.enabled !== false, models: Array.isArray(detail.model_entries) ? detail.model_entries as ChannelForm['models'] : Array.isArray(detail.models) ? detail.models.map((model) => ({ model: String(model) })) : [], api_keys: keys.map((key) => ({ api_key: String(key.api_key ?? ''), note: String(key.note ?? ''), allowed_models: Array.isArray(key.allowed_models) ? key.allowed_models.map(String) : [], detected_models: Array.isArray(key.detected_models) ? key.detected_models.map(String) : [], model_scope_empty: Boolean(key.model_scope_empty), cost_multiplier: Number(key.cost_multiplier ?? 1), priority: Number(key.priority ?? 0), disabled: Boolean(key.disabled), cooldown_until: Number(key.cooldown_until ?? 0) })) , key_strategy: String(detail.key_strategy ?? 'sequential'), rpm_limit: Number(detail.rpm_limit ?? 0), max_concurrency: Number(detail.max_concurrency ?? 0), proxy_url: String(detail.proxy_url ?? ''), websockets: Boolean(detail.websockets), protocol_transform_mode: String(detail.protocol_transform_mode ?? ''), retry_other_keys_on_failure: Boolean(detail.retry_other_keys_on_failure) }) }
  const parseAdvanced = (value: string, fallback: unknown) => { try { return JSON.parse(value) } catch { return fallback } }
  const validateRules = (value: string, kind: 'custom' | 'cooldown') => { const parsed = parseAdvanced(value, null); if (!parsed || typeof parsed !== 'object') return false; if (kind === 'custom') { const headers = Array.isArray(parsed.headers) ? parsed.headers : []; const body = Array.isArray(parsed.body) ? parsed.body : []; return headers.length <= 32 && body.length <= 32 && headers.every((rule: Record<string, unknown>) => ['remove', 'override', 'append'].includes(String(rule.action)) && String(rule.name ?? '').trim()) && body.every((rule: Record<string, unknown>) => ['remove', 'override'].includes(String(rule.action)) && /^[A-Za-z0-9_.-]+$/.test(String(rule.path ?? ''))) } const rules = Array.isArray(parsed.rules) ? parsed.rules : []; return rules.length <= 32 && rules.every((rule: Record<string, unknown>) => ['key', 'model', 'channel'].includes(String(rule.scope ?? 'key')) && ['fixed', 'reset_time'].includes(String(rule.mode ?? 'fixed')) && (Array.isArray(rule.status_codes) || String(rule.message_pattern ?? '').trim())) }
  const save = async () => { if (!validateRules(customRules, 'custom') || !validateRules(cooldownRules, 'cooldown')) { window.alert('高级规则格式无效，请检查 JSON、动作、路径和匹配条件'); return } const models = form.models.map((entry) => typeof entry === 'string' ? { model: entry.trim() } : entry).filter((entry) => entry.model); const api_keys = (form.api_keys ?? []).map((entry) => typeof entry === 'string' ? { api_key: entry.trim() } : entry).filter((entry) => entry.api_key); const payload = { ...form, models, api_keys, custom_request_rules: parseAdvanced(customRules, undefined), cooldown_detection_rules: parseAdvanced(cooldownRules, undefined), management_account: parseAdvanced(management, undefined) }; if (editing) await putJSON(`/admin/channels/${editing.id}`, payload); else await postJSON('/admin/channels', payload); setEditing(null); query.refresh() }
  const remove = async (channel: Channel) => { if (window.confirm(`确定删除渠道“${channel.name}”？`)) { await deleteJSON(`/admin/channels/${channel.id}`); query.refresh() } }
  const toggleURL = async (url: string, disabled: boolean) => { if (!editing) return; await postJSON(`/admin/channels/${editing.id}/${disabled ? 'url-disable' : 'url-enable'}`, { url }); setUrlStats((items) => items.map((item) => item.url === url ? { ...item, disabled } : item)) }
  const toggleKey = async (index: number, disabled: boolean) => { if (!editing) return; await postJSON(`/admin/channels/${editing.id}/${disabled ? 'key-disable' : 'key-enable'}`, { key_index: index }); setKeyStates((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, disabled } : item)) }
  const testKey = async (index: number) => { if (!editing) return; const entry = form.api_keys?.[index]; const key = typeof entry === 'string' ? entry : entry?.api_key; const model = form.models[0]; const modelName = typeof model === 'string' ? model : model?.model; if (!key || !modelName) return; setChannelOperationResult(await postJSON(`/admin/channels/${editing.id}/test`, { model: modelName, stream: true, content: 'test', client_protocol: 'anthropic', key_index: index, api_key: key })) }
